export default class CustomCursor {
    // Structural optimization: Cache elements and sizes to eliminate DOM reads
    #cursor!: HTMLDivElement;
    #mouseX: number = 0;
    #mouseY: number = 0;
    #currentX: number = 0;
    #currentY: number = 0;
    #lastMoveTime: number = 0;
    #rafId: number = 0; // Uses numeric 0 instead of null to prevent type-switching in JS engines  
    // Flattened state control using bitwise flags (0 = resting, 1 = moving, 2 = interactive active)
    #stateFlags: number = 0; 
    // Constant configuration variables
    readonly #closeness: number = 0.55;
    readonly #halfWidth: number = 10;
    readonly #halfHeight: number = 10;
    // Strict type definitions for event references
    readonly #boundMouseMove: (e: MouseEvent) => void;
    readonly #boundMouseOver: (e: MouseEvent) => void;

    constructor() {
        // Micro-optimization: Pre-bind functions exactly once during construction
        this.#boundMouseMove = this.#onMouseMove.bind(this);
        this.#boundMouseOver = this.#handleInteractivity.bind(this);

        if (typeof window !== 'undefined' && window.matchMedia('(pointer: fine)').matches) {
            this.#createCursorElement();
            this.#init();
        }
    }

    #createCursorElement(): void {
        const doc: Document = document;
        const el: HTMLDivElement = doc.createElement('div');
        el.className = 'cursor';
        // Inline assignment is significantly faster than Object.assign polyfills
        const style: CSSStyleDeclaration = el.style;
        style.position = 'fixed';
        style.top = '0';
        style.left = '0';
        style.pointerEvents = 'none';
        style.display = 'none';
        style.willChange = 'transform';
        this.#cursor = el;
        doc.body.appendChild(el);
    }

    #init(): void {
        this.#lastMoveTime = performance.now();
        const win = window;
        win.addEventListener('mousemove', this.#boundMouseMove, { passive: true });
        win.addEventListener('mouseover', this.#boundMouseOver, { passive: true });
    }

    #onMouseMove(e: MouseEvent): void {
        this.#mouseX = e.clientX;
        this.#mouseY = e.clientY;
        this.#lastMoveTime = performance.now();

        // 1. Bitwise flag evaluation: checks if closeness logic can be skipped entirely
        if (this.#closeness >= 1.0) {
            this.#cursor.style.display = 'block';
            // Bitwise double NOT (~~) replaces Math.round for instant float-to-integer parsing
            this.#cursor.style.transform = `matrix(1,0,0,1,${~~(this.#mouseX - this.#halfWidth)},${~~(this.#mouseY - this.#halfHeight)})`;
            return;
        }

        // 2. State management checking using fast bitwise mask calculations
        if ((this.#stateFlags & 1) === 0) {
            this.#stateFlags |= 1; // Mark as moving
            this.#cursor.style.display = 'block';
            
            if (this.#rafId === 0) {
                this.#rafId = requestAnimationFrame(this.#tick);
            }
        }
    }

    // Arrow function format prevents context re-binding overhead inside the RAF engine loop
    #tick = (timestamp: number): void => {
        const closeness: number = this.#closeness;
        
        // Linear Interpolation physics tracking calculation
        this.#currentX += (this.#mouseX - this.#currentX) * closeness;
        this.#currentY += (this.#mouseY - this.#currentY) * closeness;

        // Optimization: Using 2D matrix transformation bypasses translation-string parsing overhead in modern browsers
        this.#cursor.style.transform = `matrix(1,0,0,1,${~~(this.#currentX - this.#halfWidth)},${~~(this.#currentY - this.#halfHeight)})`;

        const deltaX: number = this.#mouseX - this.#currentX;
        const deltaY: number = this.#mouseY - this.#currentY;
        const distanceSquared: number = (deltaX * deltaX) + (deltaY * deltaY);

        // Cull condition verification
        if (distanceSquared < 0.01 && (timestamp - this.#lastMoveTime) > 1200) {
            this.#cursor.style.display = 'none';
            this.#stateFlags &= ~1; // Clear moving state bitmask
            this.#rafId = 0; 
            return;
        }

        this.#rafId = requestAnimationFrame(this.#tick);
    };

    #handleInteractivity(e: MouseEvent): void {
        const target = e.target as HTMLElement | null;
        if (!target) return;
        // Uses highly optimized tag matching before defaulting to full upward tree lookups
        const tag: string = target.tagName;
        const isInteractive: boolean = tag === 'A' || tag === 'BUTTON' || target.classList.contains('interactive') || !!target.closest('a, button, .interactive');
        const activeState: boolean = (this.#stateFlags & 2) !== 0;

        if (isInteractive && !activeState) {
            this.#stateFlags |= 2; // Set interactive bitmask
            this.#cursor.classList.add('active');
        } else if (!isInteractive && activeState) {
            this.#stateFlags &= ~2; // Clear interactive bitmask
            this.#cursor.classList.remove('active');
        }
    }

    destroy(): void {
        if (this.#rafId !== 0) {
            cancelAnimationFrame(this.#rafId);
            this.#rafId = 0;
        }
        
        const win = window;
        win.removeEventListener('mousemove', this.#boundMouseMove);
        win.removeEventListener('mouseover', this.#boundMouseOver);
        
        this.#cursor.remove();
        this.#stateFlags = 0;
    }
}